  1→import { ComponentFixture, TestBed } from '@angular/core/testing';
  2→import { FretboardFlashPageComponent } from './fretboard-flash-page';
  3→import { GameStateService } from '../game-state.service';
  4→import { ProgressionService } from '../progression.service';
  5→import { FretNote } from '../note-data';
  6→
  7→describe('FretboardFlashPageComponent', () => {
  8→  let fixture: ComponentFixture<FretboardFlashPageComponent>;
  9→  let nativeElement: HTMLElement;
 10→  let gameStateService: GameStateService;
 11→  let progressionService: ProgressionService;
 12→
 13→  const testNote: FretNote = { string: 1, fret: 3, note: 'G', x: 22, y: 8 };
 14→
 15→  beforeEach(async () => {
 16→    await TestBed.configureTestingModule({
 17→      imports: [FretboardFlashPageComponent],
 18→    }).compileComponents();
 19→
 20→    fixture = TestBed.createComponent(FretboardFlashPageComponent);
 21→    nativeElement = fixture.nativeElement;
 22→    // Services are component-provided, so retrieve from the component's injector
 23→    gameStateService = fixture.debugElement.injector.get(GameStateService);
 24→    progressionService = fixture.debugElement.injector.get(ProgressionService);
 25→  });
 26→
 27→  describe('idle state', () => {
 28→    it('should display a start button when the game is idle', () => {
 29→      fixture.detectChanges();
 30→
 31→      const startButton = nativeElement.querySelector('[data-testid="start-button"]');
 32→      expect(startButton).toBeTruthy();
 33→    });
 34→
 35→    it('should not display a stop button when the game is idle', () => {
 36→      fixture.detectChanges();
 37→
 38→      const stopButton = nativeElement.querySelector('[data-testid="stop-button"]');
 39→      expect(stopButton).toBeNull();
 40→    });
 41→
 42→    it('should not display a note letter when the game is idle', () => {
 43→      fixture.detectChanges();
 44→
 45→      const noteDisplay = nativeElement.querySelector('[data-testid="note-display"]');
 46→      expect(noteDisplay).toBeNull();
 47→    });
 48→
 49→    it('should display the fretboard component even when idle', () => {
 50→      fixture.detectChanges();
 51→
 52→      const fretboard = nativeElement.querySelector('app-fretboard-display');
 53→      expect(fretboard).toBeTruthy();
 54→    });
 55→  });
 56→
 57→  describe('start button', () => {
 58→    it('should start the game when the start button is clicked', () => {
 59→      fixture.detectChanges();
 60→      vi.spyOn(gameStateService, 'start');
 61→
 62→      const startButton = nativeElement.querySelector('[data-testid="start-button"]') as HTMLElement;
 63→      startButton.click();
 64→
 65→      expect(gameStateService.start).toHaveBeenCalled();
 66→    });
 67→  });
 68→
 69→  describe('SHOW_NOTE state', () => {
 70→    beforeEach(() => {
 71→      vi.spyOn(progressionService, 'drawNote').mockReturnValue(testNote);
 72→      gameStateService.start();
 73→      fixture.detectChanges();
 74→    });
 75→
 76→    it('should display the current note letter prominently', () => {
 77→      const noteDisplay = nativeElement.querySelector('[data-testid="note-display"]');
 78→      expect(noteDisplay).toBeTruthy();
 79→      expect(noteDisplay!.textContent!.trim()).toBe('G');
 80→    });
 81→
 82→    it('should not pass the note to the fretboard display during SHOW_NOTE', () => {
 83→      const fretboard = nativeElement.querySelector('app-fretboard-display');
 84→      expect(fretboard).toBeTruthy();
 85→      const marker = fretboard!.querySelector('[data-testid="note-marker"]');
 86→      expect(marker).toBeNull();
 87→    });
 88→
 89→    it('should display a stop button instead of start', () => {
 90→      const startButton = nativeElement.querySelector('[data-testid="start-button"]');
 91→      const stopButton = nativeElement.querySelector('[data-testid="stop-button"]');
 92→      expect(startButton).toBeNull();
 93→      expect(stopButton).toBeTruthy();
 94→    });
 95→  });
 96→
 97→  describe('SHOW_ANSWER state', () => {
 98→    beforeEach(() => {
 99→      vi.spyOn(progressionService, 'drawNote').mockReturnValue(testNote);
100→      gameStateService.start();
101→      gameStateService.showAnswer();
102→      fixture.detectChanges();
103→    });
104→
105→    it('should still display the note letter during SHOW_ANSWER', () => {
106→      const noteDisplay = nativeElement.querySelector('[data-testid="note-display"]');
107→      expect(noteDisplay).toBeTruthy();
108→      expect(noteDisplay!.textContent!.trim()).toBe('G');
109→    });
110→
111→    it('should pass the note to the fretboard display so the marker is shown', () => {
112→      const marker = nativeElement.querySelector('[data-testid="note-marker"]');
113→      expect(marker).toBeTruthy();
114→    });
115→
116→    it('should display a stop button during SHOW_ANSWER', () => {
117→      const stopButton = nativeElement.querySelector('[data-testid="stop-button"]');
118→      expect(stopButton).toBeTruthy();
119→    });
120→  });
121→
122→  describe('stop button', () => {
123→    it('should stop the game when the stop button is clicked', () => {
124→      vi.spyOn(progressionService, 'drawNote').mockReturnValue(testNote);
125→      gameStateService.start();
126→      fixture.detectChanges();
127→
128→      vi.spyOn(gameStateService, 'stop');
129→      const stopButton = nativeElement.querySelector('[data-testid="stop-button"]') as HTMLElement;
130→      stopButton.click();
131→
132→      expect(gameStateService.stop).toHaveBeenCalled();
133→    });
134→
135→    it('should return to idle state after stopping', () => {
136→      vi.spyOn(progressionService, 'drawNote').mockReturnValue(testNote);
137→      gameStateService.start();
138→      fixture.detectChanges();
139→
140→      gameStateService.stop();
141→      fixture.detectChanges();
142→
143→      const startButton = nativeElement.querySelector('[data-testid="start-button"]');
144→      const noteDisplay = nativeElement.querySelector('[data-testid="note-display"]');
145→      expect(startButton).toBeTruthy();
146→      expect(noteDisplay).toBeNull();
147→    });
148→  });
149→
150→  describe('note display updates', () => {
151→    it('should update the displayed note letter when the current note changes', () => {
152→      const firstNote: FretNote = { string: 6, fret: 0, note: 'E', x: 1.5, y: 92 };
153→      const secondNote: FretNote = { string: 5, fret: 0, note: 'A', x: 1.5, y: 75 };
154→      vi.spyOn(progressionService, 'drawNote')
155→        .mockReturnValueOnce(firstNote)
156→        .mockReturnValueOnce(secondNote);
157→
158→      gameStateService.start();
159→      fixture.detectChanges();
160→      expect(nativeElement.querySelector('[data-testid="note-display"]')!.textContent!.trim()).toBe('E');
161→
162→      gameStateService.showAnswer();
163→      gameStateService.nextNote();
164→      fixture.detectChanges();
165→      expect(nativeElement.querySelector('[data-testid="note-display"]')!.textContent!.trim()).toBe('A');
166→    });
167→  });
168→});
169→

