  1→import { ComponentFixture, TestBed } from '@angular/core/testing';
  2→import { FretboardDisplayComponent } from './fretboard-display';
  3→import { FretNote } from '../note-data';
  4→
  5→describe('FretboardDisplayComponent', () => {
  6→  let fixture: ComponentFixture<FretboardDisplayComponent>;
  7→  let component: FretboardDisplayComponent;
  8→  let nativeElement: HTMLElement;
  9→
 10→  beforeEach(async () => {
 11→    await TestBed.configureTestingModule({
 12→      imports: [FretboardDisplayComponent],
 13→    }).compileComponents();
 14→
 15→    fixture = TestBed.createComponent(FretboardDisplayComponent);
 16→    component = fixture.componentInstance;
 17→    nativeElement = fixture.nativeElement;
 18→  });
 19→
 20→  it('should display the fretboard SVG image with root-relative path', () => {
 21→    fixture.detectChanges();
 22→
 23→    const img = nativeElement.querySelector('[data-testid="fretboard-image"]');
 24→    expect(img).toBeTruthy();
 25→    expect(img!.getAttribute('src')).toBe('/images/fretboard.svg');
 26→    expect(img!.getAttribute('alt')).toBeTruthy();
 27→  });
 28→
 29→  it('should have a relative-positioned wrapper around the image', () => {
 30→    fixture.detectChanges();
 31→
 32→    const wrapper = nativeElement.querySelector('[data-testid="fretboard-wrapper"]');
 33→    expect(wrapper).toBeTruthy();
 34→    expect(wrapper!.classList.contains('fretboard-wrapper')).toBe(true);
 35→  });
 36→
 37→  it('should have an overlay container positioned over the image', () => {
 38→    fixture.detectChanges();
 39→
 40→    const overlay = nativeElement.querySelector('[data-testid="fretboard-overlay"]');
 41→    expect(overlay).toBeTruthy();
 42→    expect(overlay!.classList.contains('fretboard-overlay')).toBe(true);
 43→  });
 44→
 45→  it('should not render a note marker when no note is provided', () => {
 46→    fixture.detectChanges();
 47→
 48→    const marker = nativeElement.querySelector('[data-testid="note-marker"]');
 49→    expect(marker).toBeNull();
 50→  });
 51→
 52→  it('should render a note marker dot when a note is provided', () => {
 53→    const testNote: FretNote = { string: 1, fret: 3, note: 'G', x: 22, y: 8 };
 54→    fixture.componentRef.setInput('note', testNote);
 55→    fixture.detectChanges();
 56→
 57→    const marker = nativeElement.querySelector('[data-testid="note-marker"]');
 58→    expect(marker).toBeTruthy();
 59→  });
 60→
 61→  it('should position the note marker at the x/y percentages from the note', () => {
 62→    const testNote: FretNote = { string: 3, fret: 5, note: 'C', x: 36.3, y: 42 };
 63→    fixture.componentRef.setInput('note', testNote);
 64→    fixture.detectChanges();
 65→
 66→    const marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
 67→    expect(marker).toBeTruthy();
 68→    expect(marker.style.left).toBe('36.3%');
 69→    expect(marker.style.top).toBe('42%');
 70→  });
 71→
 72→  it('should remove the note marker when the note is set to null', () => {
 73→    const testNote: FretNote = { string: 1, fret: 0, note: 'E', x: 1.5, y: 8 };
 74→    fixture.componentRef.setInput('note', testNote);
 75→    fixture.detectChanges();
 76→
 77→    expect(nativeElement.querySelector('[data-testid="note-marker"]')).toBeTruthy();
 78→
 79→    fixture.componentRef.setInput('note', null);
 80→    fixture.detectChanges();
 81→
 82→    expect(nativeElement.querySelector('[data-testid="note-marker"]')).toBeNull();
 83→  });
 84→
 85→  it('should update the marker position when the note changes', () => {
 86→    const firstNote: FretNote = { string: 1, fret: 3, note: 'G', x: 22, y: 8 };
 87→    fixture.componentRef.setInput('note', firstNote);
 88→    fixture.detectChanges();
 89→
 90→    let marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
 91→    expect(marker.style.left).toBe('22%');
 92→    expect(marker.style.top).toBe('8%');
 93→
 94→    const secondNote: FretNote = { string: 6, fret: 10, note: 'D', x: 65.7, y: 92 };
 95→    fixture.componentRef.setInput('note', secondNote);
 96→    fixture.detectChanges();
 97→
 98→    marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
 99→    expect(marker.style.left).toBe('65.7%');
100→    expect(marker.style.top).toBe('92%');
101→  });
102→
103→  it('should place the note marker inside the overlay container', () => {
104→    const testNote: FretNote = { string: 2, fret: 1, note: 'C', x: 9.3, y: 25 };
105→    fixture.componentRef.setInput('note', testNote);
106→    fixture.detectChanges();
107→
108→    const overlay = nativeElement.querySelector('[data-testid="fretboard-overlay"]');
109→    const marker = overlay!.querySelector('[data-testid="note-marker"]');
110→    expect(marker).toBeTruthy();
111→  });
112→
113→  it('should apply the note-marker class to the marker element', () => {
114→    const testNote: FretNote = { string: 4, fret: 7, note: 'A', x: 49, y: 58 };
115→    fixture.componentRef.setInput('note', testNote);
116→    fixture.detectChanges();
117→
118→    const marker = nativeElement.querySelector('[data-testid="note-marker"]');
119→    expect(marker!.classList.contains('note-marker')).toBe(true);
120→  });
121→
122→  describe('responsive scaling', () => {
123→    it('should apply the fretboard-image class to the image element', () => {
124→      fixture.detectChanges();
125→
126→      const img = nativeElement.querySelector('[data-testid="fretboard-image"]') as HTMLElement;
127→      expect(img.classList.contains('fretboard-image')).toBe(true);
128→    });
129→
130→    it('should use percentage-based width on the note marker for proportional scaling', () => {
131→      const testNote: FretNote = { string: 3, fret: 5, note: 'C', x: 36.3, y: 42 };
132→      fixture.componentRef.setInput('note', testNote);
133→      fixture.detectChanges();
134→
135→      const marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
136→      expect(marker.style.width).toBe('2%');
137→    });
138→
139→    it('should not set an inline height on the marker so SCSS aspect-ratio controls the shape', () => {
140→      const testNote: FretNote = { string: 1, fret: 3, note: 'G', x: 22, y: 8 };
141→      fixture.componentRef.setInput('note', testNote);
142→      fixture.detectChanges();
143→
144→      const marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
145→      // Height is not set inline — the SCSS aspect-ratio: 1 rule ensures a circle
146→      expect(marker.style.height).toBe('');
147→    });
148→
149→    it('should not use fixed pixel dimensions on the note marker', () => {
150→      const testNote: FretNote = { string: 2, fret: 1, note: 'C', x: 9.3, y: 25 };
151→      fixture.componentRef.setInput('note', testNote);
152→      fixture.detectChanges();
153→
154→      const marker = nativeElement.querySelector('[data-testid="note-marker"]') as HTMLElement;
155→      // Width should be a percentage, not a pixel value
156→      expect(marker.style.width).not.toContain('px');
157→      // Height should not be set (aspect-ratio handles it)
158→      expect(marker.style.height).toBe('');
159→    });
160→  });
161→});
